// Ordem de exibição no seletor de avatar
const ORDEM_AVATARS = ["rinoceronte", "girafa", "alpaca", "pinguim", "urso_polar", "coala", "garca", "coruja", "coelho", "preguica", "leao", "suricato"];

// Gera o "chip" visual de um avatar: círculo colorido com o ícone do animal.
// Se a chave não existir no catálogo (participante antigo sem avatar, por exemplo),
// cai de volta para um círculo neutro com a inicial do apelido.
function renderAvatarChip(avatarKey, apelido, tamanho) {
    tamanho = tamanho || "w-8 h-8";
    const info = CATALOGO_AVATARS[avatarKey];

    if (!info) {
        const inicial = (apelido || "?").trim().charAt(0).toUpperCase() || "?";
        return `<span class="inline-flex items-center justify-center shrink-0 rounded-full bg-slate-200 dark:bg-slate-700 text-slate-600 dark:text-slate-300 font-black ${tamanho}">${inicial}</span>`;
    }

    return `<span class="inline-flex items-center justify-center shrink-0 rounded-full bg-${info.cor}-50 dark:bg-${info.cor}-900/30 text-${info.cor}-600 dark:text-${info.cor}-400 p-1.5 [&>svg]:w-full [&>svg]:h-full ${tamanho}" title="${info.nome}">${info.svg}</span>`;
}